// TEST-ONLY Worker used by tests/worker/quotation-owner.ts; never deployed or referenced by any
// wrangler config in the repository. It runs the real owner handler and email runner with
// test-only differences from the deployable entry (worker/owner/index.ts):
// - Access signing keys generated by the test run (TEST_ACCESS_JWKS, a public key), instead of
//   the team domain's published keys;
// - OWNER_ORIGIN and PUBLIC_ORIGIN may also be plain HTTP on a loopback host
//   (`localLoopbackOrigin`), because the local runtime serves http://127.0.0.1. The deployable
//   entry accepts canonical HTTPS only, and no production code imports this file;
// - the scheduled email run uses an in-memory mock provider (tests/support/mock-email.ts), never
//   a real one; GET /__test/provider reports what it received as keys, recipients and the
//   SHA-256 of each customer link (never message bodies or link tokens); GET /__test/retention runs
//   one retention pass through a metering D1 wrapper and reports its rows read and written;
//   GET /__test/provider-script?b=reject,accept_slow scripts the mock's next answers and
//   GET /__test/provider-release answers its waiting calls (tests/support/mock-email.ts).
// It refuses any request not addressed to the local loopback address, so even if it were run
// elsewhere it would serve nothing.

import { canonicalOrigin, handleOwner, validOwnerOrigin, type OwnerEnv, type OwnerOriginCheck } from '../../worker/owner/handler.ts';
import { runScheduled, runScheduledRetention, type SenderEnv } from '../../worker/owner/scheduled.ts';
import { sha256Hex } from '../../src/lib/quotation/owner-form.ts';
import { createMockProvider, type Behaviour } from '../support/mock-email.ts';
import { runRetention } from '../../worker/owner/retention.ts';
import type { D1Database, D1PreparedStatement } from '../../src/lib/quotation/d1.ts';

const LOOPBACK_HOSTS = new Set(['127.0.0.1', '[::1]', 'localhost']);

/** The deployed rule, plus canonical HTTP on a loopback host. */
export const localLoopbackOrigin: OwnerOriginCheck = (value) => {
  const url = canonicalOrigin(value);
  return validOwnerOrigin(value) || (url?.protocol === 'http:' && LOOPBACK_HOSTS.has(url.hostname));
};

const provider = createMockProvider(20);

export default {
  async fetch(request: Request, env: OwnerEnv & { TEST_ACCESS_JWKS?: string }): Promise<Response> {
    const url = new URL(request.url);
    if (url.hostname !== '127.0.0.1' || !env.TEST_ACCESS_JWKS) return new Response('Not found', { status: 404 });
    if (url.pathname === '/__test/retention') {
      // Test-only: one retention run at a given time, through a D1 wrapper that sums D1's own
      // rows_read / rows_written for every statement (populated-database cost check).
      const cost = { read: 0, written: 0, statements: 0 };
      const add = (meta: unknown) => {
        const m = (meta ?? {}) as { rows_read?: number; rows_written?: number };
        cost.statements++;
        cost.read += m.rows_read ?? 0;
        cost.written += m.rows_written ?? 0;
      };
      type Wrapped = D1PreparedStatement & { real: D1PreparedStatement };
      const wrap = (real: D1PreparedStatement): Wrapped => ({
        real,
        bind: (...values) => wrap(real.bind(...values)),
        all: async <T>() => {
          const r = await real.all<T>();
          add(r.meta);
          return r;
        },
        run: async () => {
          const r = await real.run();
          add(r.meta);
          return r;
        },
        first: async <T>() => {
          const r = await real.all<T>();
          add(r.meta);
          return (r.results[0] as T | undefined) ?? null;
        },
      });
      const db: D1Database = {
        prepare: (sql) => wrap(env.DB!.prepare(sql)),
        batch: async <T>(statements: D1PreparedStatement[]) => {
          const results = await env.DB!.batch<T>(statements.map((s) => (s as Wrapped).real));
          for (const r of results) add(r.meta);
          return results;
        },
      };
      const summary = await runRetention(db, Number(url.searchParams.get('now') ?? Date.now()));
      return Response.json({ summary, cost });
    }
    if (url.pathname === '/__test/provider-script') {
      provider.script.push(...((url.searchParams.get('b') ?? '').split(',') as Behaviour[]));
      return Response.json({ script: provider.script });
    }
    if (url.pathname === '/__test/provider-release') {
      provider.release();
      return Response.json({ released: true });
    }
    if (url.pathname === '/__test/provider') {
      const linkHashes = await Promise.all(
        provider.inbox.map(async (entry) => {
          const token = /#t=(v\d+\.[A-Za-z0-9_-]{43})/.exec(entry.message.text)?.[1];
          return token ? sha256Hex(token) : null;
        }),
      );
      return Response.json({
        calls: provider.calls,
        inbox: provider.inbox.map((entry, i) => ({ key: entry.key, to: entry.message.to, linkHash: linkHashes[i] })),
      });
    }
    const keys = (JSON.parse(env.TEST_ACCESS_JWKS) as { keys: (JsonWebKey & { kid: string })[] }).keys;
    return handleOwner(request, env, async (kid) => keys.find((key) => key.kid === kid) ?? null, Date.now(), localLoopbackOrigin);
  },

  async scheduled(_controller: unknown, env: SenderEnv): Promise<void> {
    // Quotation emails are enabled here only: the deployable entry uses the committed readiness constant (off).
    await runScheduledRetention(env, () => Date.now(), localLoopbackOrigin);
    await runScheduled(env, () => provider.transport, () => Date.now(), localLoopbackOrigin, { quotationEmailsReady: true });
  },
};
